                        + "ORDER BY stamp_nanos ASC FETCH FIRST 1 ROWS ONLY",
                edgeId, stampNanos);
    }

    @Override
    public Optional<Long> deleteSamplesOlderThan(long edgeId, long cutoffNanos) {
        List<Long> oldest = jdbcTemplate.queryForList(
                "SELECT MIN(stamp_nanos) FROM tf_dynamic_sample WHERE edge_id = ? AND stamp_nanos < ?",
                Long.class, edgeId, cutoffNanos);
