/** 取边在 stampNanos 时刻的位姿：静态全时刻有效，动态在相邻样本间插值。 */
private Transform3d evaluate(EdgeRow edge, long stampNanos) {
    String edgeLabel = edge.parentFrame() + " -> " + edge.childFrame();
    if (edge.edgeType() == EdgeType.STATIC) {
        return repository.findStaticPose(edge.id())
                .map(JdbcTfRepositoryMappers::toTransform)
                .orElseThrow(() -> new IllegalStateException("静态边缺少位姿: edgeId=" + edge.id()));
    }

    SampleRow before = repository.findSampleAtOrBefore(edge.id(), stampNanos).orElse(null);
    SampleRow after = repository.findSampleAtOrAfter(edge.id(), stampNanos).orElse(null);

    if (before == null) {
        // 没有不晚于查询时刻的保留样本：要么被窗口淘汰，要么本来就早于最早采样
        if (edge.evictedUptoNanos() != null && stampNanos <= edge.evictedUptoNanos()) {
            throw new TfException.CacheWindowExceeded(
                    edgeLabel, stampNanos, edge.evictedUptoNanos() + 1);
        }
        long earliest = after == null ? stampNanos : after.stampNanos();
        throw new TfException.BeforeEarliestSample(edgeLabel, stampNanos, earliest);
    }
    if (after == null) {
        throw new TfException.AfterLatestSample(edgeLabel, stampNanos, before.stampNanos());
    }
    if (after.stampNanos() == before.stampNanos()) {
        return JdbcTfRepositoryMappers.toTransform(after);
    }
    double alpha = (double) (stampNanos - before.stampNanos())
            / (double) (after.stampNanos() - before.stampNanos());
    return Transform3d.interpolate(
            JdbcTfRepositoryMappers.toTransform(before),
            JdbcTfRepositoryMappers.toTransform(after),
            alpha);
}

private static boolean isDynamic(EdgeRow edge) {
    return edge.edgeType() == EdgeType.DYNAMIC;
}

